changeSet.sql:
ALTER TABLE role ADD CONSTRAINT ck_role_scope CHECK (
    NOT (school_id IS NOT NULL AND tenant_id IS NOT NULL)
    );
ALTER TABLE role ADD CONSTRAINT ck_role_access_scope CHECK (
    access_scope IN ('SYSTEM', 'TENANT', 'ASSIGNED_SCHOOLS', 'OWN')
    );

ALTER TABLE permission ADD CONSTRAINT ck_permission_resource_scope CHECK (
    resource_scope IN ('SYSTEM', 'TENANT', 'SCHOOL')
    );

ALTER TABLE tenant
    ADD CONSTRAINT ck_tenant_code_format
        CHECK (code ~ '^[A-Z0-9]{6}$');

CREATE UNIQUE INDEX uk_enrollment_learner_active_year
    ON enrollment (learner_id, academic_year_id)
    WHERE status = 'ACTIVE';

ALTER TABLE tenant ENABLE ROW LEVEL SECURITY;
ALTER TABLE school ENABLE ROW LEVEL SECURITY;
ALTER TABLE code_set ENABLE ROW LEVEL SECURITY;
ALTER TABLE app_user_school ENABLE ROW LEVEL SECURITY;
ALTER TABLE learner ENABLE ROW LEVEL SECURITY;
ALTER TABLE class_section ENABLE ROW LEVEL SECURITY;
ALTER TABLE enrollment ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance ENABLE ROW LEVEL SECURITY;
ALTER TABLE change_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE sync_conflict ENABLE ROW LEVEL SECURITY;

            CREATE POLICY tenant_isolation ON tenant
USING (
current_setting('app.is_platform_admin', true) = 'true'
OR id::text = current_setting('app.current_tenant_id', true)
);
CREATE POLICY school_isolation ON school
USING (
current_setting('app.is_platform_admin', true) = 'true'
OR tenant_id::text = current_setting('app.current_tenant_id', true)
OR id IN (
SELECT school_id FROM app_user_school
WHERE app_user_id::text = current_setting('app.current_user_id', true)
)
);
CREATE POLICY app_user_school_isolation ON app_user_school
USING (
current_setting('app.is_platform_admin', true) = 'true'
OR app_user_id::text = current_setting('app.current_user_id', true)
OR school_id IN (
SELECT id FROM school
WHERE tenant_id::text = current_setting('app.current_tenant_id', true)
)
);
-- ✅ CHANGED: code_set now filters directly by tenant_id (no school join needed)
